responses.text:
{
  "instrument": "§ 356a BGB — IHK explainer on the Widerrufsbutton",
  "jurisdiction": "DE",
  "summary": "Richten Sie bis zum 19. Juni 2026 eine Widerrufsfunktion mit Bestätigungsseite ein und senden Sie nach jedem Widerruf unverzüglich eine Eingangsbestätigung. Die IHK-Seite fasst § 356a BGB für Online-Shops zusammen.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Senden Sie nach dem Widerruf unverzüglich eine Eingangsbestätigung, etwa per E-Mail.",
      "quote": "Nach dem Widerruf ist dem Kunden unverzüglich eine Eingangsbestätigung auf einem dauerhaften Datenträger, etwa per E-Mail, zu übermitteln."
    }
  ]
}
